# The list of material pictures of the six places after the Heart, with the prompt of each.
# Kinds: tile (repeats both ways, colour and height data), sky (a sky picture), plate (one whole feature on black, not repeated).
# Run: python3 assets-src/materials/spec.py   (writes assets-src/materials/spec.json, which the generation step and the recipe writer read)
import json, os

TILE = ("Flat, even, shadowless overcast light so that no side is brighter than another. The surface fills the whole frame edge to edge at one uniform scale, as a seamless tileable texture. "
        "The first reference image is the place this material belongs to: take its colours, its age and its character from there, and nothing of its composition. "
        "The second reference image is a real photograph: it is the standard for how a camera records a real surface, with real grain, real micro detail and no painted or stylised look. "
        "Output one square image. Photographic, sharp from edge to edge, no depth of field blur, no vignette, no horizon, no sky, no text, no logo, no people, no animals.")
SKY = ("The bottom edge of the frame lies just above the horizon and the top edge is high overhead: only sky and cloud, no land, no sea, no rocks, no mountains, no birds, no sun disc. "
       "The first reference image is the place this sky belongs to: take its cloud forms, its colour and its light from there. "
       "The second reference image is a real photograph: it is the standard for how a camera records a real sky, with real soft gradients, real cloud structure and no painted or stylised look. "
       "Output one wide landscape image, three units wide and two tall. Photographic, no text, no logo, no people.")
DOWN = "A material texture, seen straight down from above in an orthographic view: "
FACE = "A material texture, seen square on in an orthographic view: "
A = 'references/approved/'
R = 'references/drafts/working/real/'

def ap(place, n):
    d = {'ribs': '1-ribs', 'breath': '3-breath', 'marsh': '4-marsh', 'spine': '5-spine', 'eye': '6-eye', 'reveal': '7-reveal'}[place]
    f = [x for x in sorted(os.listdir(A + d)) if x.startswith(f'{place}-{n}-')][0]
    return A + d + '/' + f

rows = []
def tile(place, name, head, key, real, why, metres):
    rows.append(dict(place=place, name=name, kind='tile', prompt=head + ' ' + TILE, refs=[ap(place, key), R + real], why=why, metres=metres))
def sky(place, head, key, real, why):
    rows.append(dict(place=place, name='sky', kind='sky', prompt=head + ' ' + SKY, refs=[ap(place, key), R + real], why=why, metres=0))

# The Ribs
tile('ribs', 'bone', FACE + "the surface of a colossal ancient rib that stands in the sea like a stone arch, a section about 12 metres across. Weathered bone turned half to stone: pale grey-cream and ivory, with long shallow grooves and fine cracks running from top to bottom, pitted and porous patches where the surface has flaked away, darker grey water stains, streaks of green-black algae running down and a little rust-orange lichen. The grooves run exactly vertical.", 0, 'plate-surf-1.jpg', 'the ribs themselves, which the establishing picture shows as pale grooved bone-stone with dark stains', 12)
tile('ribs', 'weed', FACE + "the face of a sea cliff at low tide, a section about 8 metres tall, completely draped in hanging seaweed. Thick wet curtains of dark olive, brown-black and ochre-orange kelp and wrack hanging straight down in overlapping strands, glistening wet, with patches of dark barnacled rock showing between them. The strands hang exactly vertical.", 1, 'plate-surf-1.jpg', 'the weed-hung cliff of the left foreground and of the detail of the drowned one', 8)
tile('ribs', 'flat', DOWN + "a tidal flat just after the sea has left it, about 4 metres across. Wet dark grey sand and fine gravel with shallow ripple marks, scattered small pebbles, shell grit and torn scraps of dark weed, darker where it is wettest. No standing pools and no reflections of the sky.", 2, 'plate-surf-1.jpg', 'the floor of the strait at low tide; the films of water on it are drawn by the place', 4)
tile('ribs', 'rock', DOWN + "wet dark shore rock at low tide, about 3 metres across. Rough black-brown rock crusted with grey-white barnacles, tufts of ochre and olive weed lying flat, small limpets, pits that hold grit and broken shell.", 2, 'plate-surf-1.jpg', 'the near rocks of the foreground in the establishing picture and the feeders detail', 3)
tile('ribs', 'ledge', FACE + "the face of a sea stack where a colony of flying animals roosts, a section about 10 metres tall. Stepped ledges of pale grey-white weathered rock in rough horizontal courses, heavily streaked with white droppings that run down from every ledge, with patches of bright orange and rust lichen and dark wet seams. The courses run exactly horizontal.", 3, 'plate-surf-1.jpg', 'the stack of the colony: pale stepped rock, white streaks, orange lichen', 10)
tile('ribs', 'wing', "A material texture, seen straight on: the skin of the wing of a large flying animal, stretched flat, about 1 metre across. Thin leathery membrane, pale cream to tan and pinkish grey, slightly translucent, with fine wrinkles, a branching net of darker veins, small scars and a few ragged scuffs. No feathers, no hair, no scales.", 2, 'ref-tissue-1.jpg', 'the membrane of the kite-wings, seen close in the feeders detail', 1)
sky('ribs', "A photograph of the sky only, in daylight just after a storm has passed over the sea. Heavy slate-grey and blue-black storm cloud in tall ragged masses that are breaking apart, with a few bright silver-white gaps where the sun is behind the cloud, darker toward the top of the frame and paler low down.", 0, 'plate-storm-1.jpg', 'the after-storm sky of the strait')

# The Breath
tile('breath', 'shelf', DOWN + "a flat shelf of pale rock around hot vents, about 6 metres across. Smooth worn pale grey and cream stone in broad low plates with rounded edges, hairline cracks, low scalloped rims of mineral crust in grey-white and faint pink-tan, damp darker patches and thin rust-brown stain along the cracks. No standing water.", 0, 'plate-porcelain-1.jpg', 'the pavement of the shelf, the largest surface of the place', 6)
tile('breath', 'strata', FACE + "the broken edge of a rock shelf at the rim of a deep pit, a section about 5 metres tall. Thin horizontal layers of pale cream, grey and tan stone, some layers jutting as ledges and some crumbled back, cracked blocks, dark damp seams between the layers and pale mineral drips. The layers run exactly horizontal.", 2, 'plate-terrace-1.jpg', 'the layered rim of the pit', 5)
tile('breath', 'hoop', FACE + "the face of one of the great pale rings that line the wall of a deep natural shaft, a band about 4 metres tall. A dense smooth pale substance between bone and worn limestone, ivory and grey-white, with a faint grain running along the band, scuffs and chipped edges, dark wet streaks and brown mineral stain running down from the top edge, and a thin crust of pale scale. The grain runs exactly horizontal.", 4, 'plate-terrace-1.jpg', 'the hoops of the shaft, which the detail shows as pale worn bands with wet streaks', 4)
tile('breath', 'wall', FACE + "the wall of a deep natural shaft, wet, a section about 6 metres tall. Dark grey-brown rock, rough and ribbed, glistening with seep water, with vertical streaks of black slime and pale mineral and small ledges that hold grit.", 4, 'plate-tube-1.jpg', 'the dark wall between the hoops', 6)
tile('breath', 'cliff', FACE + "the face of a great cliff of pale layered rock, a section about 200 metres tall, seen from far away. Horizontal strata in grey, cream and tan, ledges dusted with snow, dark overhangs and shadowed hollows, small scree fans on the ledges and vertical dark stains. The strata run exactly horizontal.", 0, 'plate-ridge-1.jpg', 'the far cliff with its cave band and snow', 200)
tile('breath', 'skin', "A material texture, seen straight on: the skin of a tall thin wading animal, stretched over bone, about 0.6 metres across. Pale pinkish grey and cream skin, thin and slightly translucent, with fine wrinkles, faint blue-grey veins, low ridges where ribs and tendons press through from beneath, small blotches and scars. No hair, no feathers, no scales.", 1, 'ref-hide-1.jpg', 'the skin of the waders, alive and dead', 0.6)
sky('breath', "A photograph of the sky only, soon after sunrise over a field of hot vents, seen through thin fog and steam. A pale warm sky, cream and soft peach on the side nearest the low sun, which is outside the frame beyond the upper left corner, turning to grey-mauve away from it, with thin flat layers of mist and a veil of high haze.", 0, 'plate-norris-2.jpg', 'the low sun through fog over the shelf')

# The Blood Marsh
tile('marsh', 'crust', DOWN + "a salt flat, about 5 metres across. A crust of dirty white and pale grey salt broken into uneven polygonal plates with raised crumbling rims and a rough crystalline surface, stained pink and rust-red along the cracks and in the hollows where red brine has dried.", 0, 'plate-porcelain-1.jpg', 'the flats between the channels', 5)
tile('marsh', 'mud', DOWN + "the wet margin of a pool of blood-red brine, about 2 metres across. Slick dark red-brown mud, glistening, with paler drying patches, clusters of white salt crystals and crusted froth, small bubble holes and thin dark red films.", 1, 'plate-porcelain-1.jpg', 'the banks of the brine and the wallows', 2)
tile('marsh', 'rock', DOWN + "weathered pale rock on a salt flat, about 4 metres across. Pale grey and cream stone, rounded, with a rough pitted surface, cracks, a thin crust of white salt in the hollows, and rust-red and pink stains where red water has run and dried.", 0, 'plate-porcelain-1.jpg', 'the near rock of the establishing picture, which the frames draw as smooth cracked clay', 4)
tile('marsh', 'hide', "A material texture, seen straight on: the hide of a huge heavy wallowing animal, about 1 metre across. Thick grey-brown skin in deep folds and coarse wrinkles, with sparse short bristles, caked with drying red-brown mud that is cracking, and a pale dusting of salt on the high folds.", 3, 'ref-hide-2.jpg', 'the wallowers, seen close in their detail', 1)
tile('marsh', 'bark', FACE + "the stem of a tall pale stalk plant, unrolled flat, a section about 1 metre tall. Pale cream and bone-white fibrous sheaths in overlapping rings, each ring with a ragged dry brown lower edge, fine vertical fibres, and pink-red stain in the joints. The rings run exactly horizontal.", 2, 'plate-forest-1.jpg', 'the stems of the stalk colony', 1)
tile('marsh', 'rime', "A material texture, seen straight on: a thick crust of salt crystals grown over the hide of a dead animal, about 0.5 metres across. Lumpy white and pale grey crystals like hoar frost and coarse sugar, in clumps with small cavities, with dirty pink-brown stain in the hollows.", 4, 'plate-porcelain-1.jpg', 'the salt on the one the crust caught, and on the old carcasses', 0.5)
sky('marsh', "A photograph of the sky only, under a flat white overcast in daylight. Bright heavy cloud, very pale grey-white with barely visible darker bellies, and in the middle distance one soft grey shaft of falling rain, slightly slanted, fading out before it reaches the bottom of the frame.", 0, 'plate-flats-1.jpg', 'the white overcast of the flats with its rain shaft')

# The Spine
tile('spine', 'spire', FACE + "the face of a huge spire of pale rock that is the weathered bone of a colossal vertebra, a section about 30 metres tall. Steep fractured slabs and flakes in tan, ochre, cream and grey-brown, sharp edged, split along long joints with deep dark cracks, with thin lines of snow lying in the cracks and on the small ledges. The joints run exactly vertical.", 2, 'plate-ridge-1.jpg', 'the spires, which the frames draw with one blotchy noise', 30)
tile('spine', 'snow', DOWN + "wind-packed snow on a high ridge, about 4 metres across. Cold blue-white snow carved by the wind into low sharp-edged ridges and scoops that all run one way, with a fine granular surface and a few small dark stones just breaking through.", 0, 'plate-ridge-1.jpg', 'the snow of the crest, which reads as a smooth sheet', 4)
tile('spine', 'rubble', DOWN + "broken rock on a high snowy ridge, about 5 metres across. Angular slabs and blocks of tan and grey-brown rock with gravel between them, half buried in drifted snow, with snow lying on one side of every block and rime ice on the edges.", 0, 'plate-ridge-1.jpg', 'the broken shoulders of the crest between snow and spire', 5)
tile('spine', 'canal', FACE + "the wall inside a tunnel that runs through a colossal bone, a section about 4 metres tall. Smooth worn pale bone-stone, ivory, cream and grey, with long shallow flutes, small pits, a glaze of clear ice, frost in the hollows and rows of short icicles hanging from the ridges. The flutes run exactly horizontal.", 4, 'plate-tube-1.jpg', 'the wall of the canal, which the frames draw stretched', 4)
tile('spine', 'shag', "A material texture, seen straight on: the coat of a large shaggy animal of the high cold, about 0.8 metres across. Long coarse hair, dirty white to cream and pale grey, hanging in thick matted locks from top to bottom, with clumps of ice and snow frozen into the tips and darker damp roots between the locks.", 4, 'ref-dusk-1.jpg', 'the coats of the ridge-runners, the herd in the canal and the dead one', 0.8)
tile('spine', 'cloudsea', "A texture seen from straight above: the top of a sea of cloud at dusk, about 10 kilometres across. Rolling grey-blue and mauve cloud tops in soft heaps and long swells, with darker valleys between them and thin wisps torn off by the wind. The cloud fills the whole frame at one uniform scale: no land, no sky, no horizon.", 0, 'plate-storm-1.jpg', 'the cloud sea below the crest, which the frames do not have', 10000)
sky('spine', "A photograph of the sky only, at dusk under a thunderstorm, seen from a high ridge above the clouds. Towering dark blue-grey and violet storm cloud fills most of the frame, heavy and layered with ragged torn undersides, paler grey-mauve where it thins, and along the bottom of the frame a narrow band of clear sky glows orange and pale yellow where the sun has just set. No lightning.", 0, 'plate-storm-1.jpg', 'the storm at dusk with its band of last light')

# The Eye
tile('eye', 'cliff', FACE + "the wall of a great basin of pale rock, a section about 120 metres tall. Massive pale limestone in thick horizontal beds, cream, buff and pale gold, with rounded overhangs, dark shadowed alcoves and shallow caves along some of the beds, vertical black and rust water stains, and steep fans of pale scree at the foot. The beds run exactly horizontal.", 0, 'plate-crater-1.jpg', 'the walls of the basin, which the frames draw flat and pale', 120)
tile('eye', 'mat', DOWN + "mats of living colour on the bed of a very shallow, perfectly clear lake, about 3 metres across. Long fine filaments in amber, rust orange, ochre and dark red, streaming all one way like combed hair, over pale cream mineral crust that shows through in patches. Seen through still clear water with no ripples and no reflections.", 2, 'plate-terrace-2.jpg', 'the amber mats of the shallows, which read as wood grain in the frames', 3)
tile('eye', 'shore', DOWN + "the dry shore of a mountain lake, about 4 metres across. Pale grey gravel and coarse sand with rounded cobbles and a few larger pale stones, a thin white mineral line and scraps of dry orange mat.", 1, 'plate-crater-1.jpg', 'the shore where the drinkers stand', 4)
tile('eye', 'sinter', DOWN + "pale mineral crust at the edge of a lake, about 3 metres across. Cream and chalk-white rock built up in thin scalloped layers, knobbly and pitted, with tan and orange stain in the hollows and fine cracks.", 3, 'plate-terrace-2.jpg', 'the pale lip where the floor of the lake stops', 3)
tile('eye', 'hide', "A material texture, seen straight on: the hide of a tall lean grazing animal, about 0.6 metres across. Very short dense hair over thin skin, pale tan and sandy fawn, slightly darker along faint ridges where ribs lie beneath, with fine creases, small scars and dust.", 1, 'ref-hide-3.jpg', 'the drinkers, which read as bare models', 0.6)
sky('eye', "A photograph of the sky only, on a clear still evening. A cloudless sky, pale warm gold and peach low down, deepening through soft blue to a deeper blue at the top, with two or three thin wisps of high cirrus that catch pink light.", 0, 'plate-crater-1.jpg', 'the clear evening over the lake')

# The Reveal: cloud seen from orbit, and the ground of its provinces seen from orbit
CLOUD = ("The sun is high overhead, so the cloud tops are evenly lit and no long shadow falls to one side. The sea beneath is pure black: no land, no coast, no sun glint. "
         "The first reference image is the world this cloud belongs to: take the colour and the softness of its cloud from there, and nothing of its composition. "
         "The second reference image is a real satellite photograph: it is the standard for how a camera in orbit records real cloud, with real soft edges, real fibrous and lumpy detail at every size and no painted or stylised look. "
         "Output one square image. Photographic, sharp, no text, no logo, no border, no grid lines, no stars.")
FIELD = "The field fills the whole frame edge to edge at one uniform scale, as a seamless tileable texture. "
WHOLE = "The whole feature lies inside the frame with black sea on every side of it, and nothing touches the edge of the frame. "
ORBIT = "A texture of the ground, seen straight down from orbit in an orthographic view: "
def cloud(name, head, real, why, metres, whole=False):
    rows.append(dict(place='reveal', name=name, kind='plate' if whole else 'tile', prompt='Cloud seen straight down from orbit in an orthographic view: ' + head + ' ' + (WHOLE if whole else FIELD) + CLOUD, refs=[A + '7-reveal/reveal-4-titan-from-orbit.jpg', R + real], why=why, metres=metres))
cloud('cells', "a field of low cloud over open ocean, about 500 kilometres across. Closed cells packed like cobbles in part of the field, grading into open rings of cloud with clear centres elsewhere, each cell lumpy and soft at the edge, thin grey veil between some of them, small ragged scraps in the gaps.", 'orb-modis-popcorn.jpg', 'the low cell cloud over the cold sea, which the frames draw as hard white blocks', 500000)
cloud('streets', "cloud streets over open ocean, about 400 kilometres across. Dozens of long parallel rows of small puffy cloud, the rows thin and separate at one side and thickening until they merge into a lumpy sheet at the other, every row ragged and beaded, never ruled straight.", 'orb-modis-streets.jpg', 'the cloud streets off the cold coasts', 400000)
cloud('veil', "high thin ice cloud over open ocean, about 800 kilometres across. Translucent white veils and long fine fibres streaming roughly one way, feathered and combed, denser in a few soft bands and almost nothing between them, the black sea showing through most of it.", 'orb-apollo17-earth.jpg', 'the high veil that moves against the low deck', 800000)
cloud('front', "one long weather front over open ocean, about 2,000 kilometres long, lying on a gentle curve from the lower left to the upper right. A broad band of thick layered cloud, smooth and bright along its spine, with a sharp ragged edge on one side and a wide fibrous veil thinning out on the other, lumpy convective towers embedded along it and scattered cells behind it.", 'orb-apollo17-earth.jpg', 'the long fronts, which the frames draw with hard lace at the edge', 2000000, True)
cloud('storm', "one great cluster of thunderstorms over open ocean, about 400 kilometres across. Several merged anvils forming one thick bright shield, with boiling overshooting tops bulging through it near the middle, radial fibres and a soft thin fringe of ice cloud at its edge, and a few small young towers beside it.", 'orb-modis-tstorm-louisiana-crop.jpg', 'the storm over the ridge, which the frames draw as a small blocky patch', 400000, True)
cloud('cyclone', "one great mature cyclone over open ocean, about 1,500 kilometres across. A dense central shield with a small clear eye, wrapped by two long spiral arms of lumpy convective cloud that tear into separate cells toward their ends, thin high outflow fibres fanning from the top, and clear black sea between the arms.", 'orb-apollo17-earth.jpg', 'the cyclone off the feet, which the frames draw as a smooth painted spiral', 1500000, True)
GROUND = TILE.replace('real surface', 'real land surface from orbit')
def ground(name, head, key, real, why, metres):
    rows.append(dict(place='reveal', name=name, kind='tile', prompt=ORBIT + head + ' ' + GROUND, refs=[A + '7-reveal/' + key, R + real], why=why, metres=metres))
ground('range', "the crest of a great mountain range, about 40 kilometres across. Sharp branching ridges of bare grey and tan rock, snow and small glaciers on the highest crests only, dark valleys with thin pale river threads, scree fans, and patches of dull green-brown growth low down. Ridges run in every direction, not all one way.", 'reveal-2-skull-massif.jpg', 'orb-iss13-oregon.jpg', 'the high ranges on the bone axes, which the frames draw with one erosion look', 40000)
ground('plain', "a dry lowland plain, about 60 kilometres across. Tan, ochre and dull olive ground crossed by braided river channels with pale gravel bars, old abandoned channels, alluvial fans, dark patches of low growth along the water and pale dusty flats between.", 'reveal-3-head-and-shoulders.jpg', 'orb-iss35-nile-sinai.jpg', 'the plains between the ranges', 60000)
ground('badland', "a high dry plateau cut by canyons, about 30 kilometres across. Buff, rust and grey layered rock, cut by branching canyons and gullies of many sizes, flat-topped mesas between them, pale dry washes on the canyon floors and darker rock on the rims.", 'reveal-2-skull-massif.jpg', 'orb-iss44-sinai.jpg', 'the eroded uplands, to break the single erosion look', 30000)
ground('shelf', "a shallow sea shelf beside a coast, about 80 kilometres across, seen through clear water. Pale sand shoals and bars in turquoise and milky green, branching tidal channels of deeper blue between them, darker beds of growth, and the colour deepening to dark blue where the shelf ends.", 'reveal-3-head-and-shoulders.jpg', 'orb-modis-bahamas.jpg', 'the shelves and shallows round the coasts', 80000)
ground('redflat', "a wide salt flat stained red, about 30 kilometres across. Crusted white and pink salt in broad pans, blood-red and rust-red shallow brine in branching pools and channels, dark mud at the edges, and pale dry ground around.", 'reveal-master.jpg', 'orb-natron.jpg', 'the red flats of the marsh province seen from orbit', 30000)

for r in rows:
    for p in r['refs']:
        assert os.path.exists(p), p
json.dump(rows, open('assets-src/materials/spec.json', 'w'), indent=1)
print(len(rows), 'pictures;', {p: sum(1 for r in rows if r['place'] == p) for p in ['ribs', 'breath', 'marsh', 'spine', 'eye', 'reveal']})
